330			}
331			if !errors.Is(err, errSentinelOutput) {
332				t.Fatalf("errors.Is must reach the writer error: %v", err)
333			}
334			if errors.Is(err, errSentinelChunkedRead) {
335				t.Fatalf("the output error must replace the read error learned after it: %v", err)
336			}
337		})
