340	// TestReadAggregateCleanEOFContractStillHolds summarizes the behavior that had
341	// to stay byte-identical through the reader rewrite: a valid final record
342	// without a trailing newline processes at clean EOF, while a damaged final
343	// record is an input error carrying its physical line number.
344	func TestReadAggregateCleanEOFContractStillHolds(t *testing.T) {
345		t.Run("valid unterminated final record processes", func(t *testing.T) {
346			input := `{"type":"event","key":"k","time":100,"value":2}` + "\n" +
347				`{"type":"watermark","time":1000}`
348			var out, late bytes.Buffer
349			if err := RunAggregate(strings.NewReader(input), 1000, &out, &late); err != nil {
350				t.Fatalf("clean EOF: %v", err)
351			}
352			want := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
353			if out.String() != want {
354				t.Fatalf("got %q, want %q", out.String(), want)
355			}
356		})
357		t.Run("damaged unterminated final record is a line-numbered input error", func(t *testing.T) {
358			input := `{"type":"event","key":"k","time":100,"value":2}` + "\n" +
359				`{"type":"watermark","time":1000`
360			var out, late bytes.Buffer
361			err := RunAggregate(strings.NewReader(input), 1000, &out, &late)
362			var ie *InputError
363			if !errors.As(err, &ie) || ie.Line != 2 {
364				t.Fatalf("error = %v, want *InputError on physical line 2", err)
365			}
366			if !strings.Contains(ie.Reason, "invalid JSON") {
367				t.Fatalf("reason = %q, want invalid JSON", ie.Reason)
368			}
369			if out.String() != "" {
370				t.Fatalf("nothing may be emitted: %q", out.String())
371			}
372		})
373	}
